import sys; sys.path.insert(0,'/tmp/work')
from model import *
from fractions import Fraction as F
import itertools, json
W={'arc_lite':400,'gsm_plus':200,'code_ms':250}   # window widths from recovery_log, in 1e-4 units

def day_max(vars_, T):
    """vars_: list of (c, lo, hi). maximize sum c x s.t. sum x = T, lo<=x<=hi. returns value or None if infeasible"""
    lo=sum(v[1] for v in vars_); hi=sum(v[2] for v in vars_)
    if T<lo or T>hi: return None
    R=T-lo; val=sum(F(v[0])*v[1] for v in vars_)
    for c,l,h in sorted(vars_, key=lambda v:-v[0]):
        take=min(R,h-l); val+=F(c)*take; R-=take
        if R==0: break
    return val

def day_width(vars_, T):
    mx=day_max(vars_,T)
    if mx is None: return None
    mn=-day_max([(-c,l,h) for c,l,h in vars_],T)
    return mx-mn

def contrast_vars(frm,to):
    Lf=L(frm); Lt=L(to); Nf=len(Lf); Nt=len(Lt)
    c={}
    for k in Lt: c[k]=F(1,Nt)
    for k in Lf: c[k]=c.get(k,0)-F(1,Nf)
    return c, Lf, Lt

def interval(frm,to):
    c,Lf,Lt=contrast_vars(frm,to)
    base=sum(c[k]*known[k] for k in c if k in known)
    lo=hi=base
    for d in byday:
        vs=[(c.get(k,0),bounds[k][0],bounds[k][1]) for k in unk_by_day[d]]
        if not vs: continue
        mx=day_max(vs,target[d]); mn=-day_max([(-a,b,e) for a,b,e in vs],target[d])
        lo+=mn; hi+=mx
    return lo,hi

def day_width_with(d, c, extra):
    """extra: dict run->(lo,hi) override bounds"""
    vs=[]
    for k in unk_by_day[d]:
        l,h=bounds[k]
        if k in extra:
            l=max(l,extra[k][0]); h=min(h,extra[k][1])
            if l>h: return None
        vs.append((c.get(k,0),l,h))
    return day_width(vs,target[d])

def outcome_ranges(k):
    """list of parameterisations: ('none',) / ('value',lo,hi) / ('window',w,lo,hi) where lo..hi is the domain of the window start"""
    kd=kind[k]
    if kd in('res','rec') or kd.startswith('sink'): return None
    l,h=bounds[k]
    if kd=='lost': return ('value',l,h)
    w=W[plan[k]['suite']]
    if h-l<w: return ('window',h-l,l,l)
    return ('window',w,l,h-w)

def ternary_max(f, lo, hi):
    """max of concave integer function f on [lo,hi]; f may return None (infeasible) at edges"""
    # shrink to feasible region: feasible set is an interval
    best=None
    while hi-lo>2:
        m1=lo+(hi-lo)//3; m2=hi-(hi-lo)//3
        f1=f(m1); f2=f(m2)
        if f1 is None and f2 is None:
            # feasible interval lies entirely on one side; scan
            return max((v for v in (f(x) for x in range(lo,hi+1)) if v is not None), default=None)
        if f1 is None: lo=m1+1; continue
        if f2 is None: hi=m2-1; continue
        if f1<f2: lo=m1+1
        elif f1>f2: hi=m2-1
        else: lo=m1; hi=m2
    for x in range(lo,hi+1):
        v=f(x)
        if v is not None and (best is None or v>best): best=v
    return best

def worst_day_width(d, c, runs, extra=None):
    """max over joint outcomes of runs (all on day d) of day width"""
    extra=dict(extra or {})
    runs=[k for k in runs if outcome_ranges(k) is not None]
    if not runs: return day_width_with(d,c,extra)
    k=runs[0]; rest=runs[1:]; o=outcome_ranges(k)
    if o[0]=='value':
        f=lambda v: worst_day_width(d,c,rest,{**extra,k:(v,v)})
        return ternary_max(f,o[1],o[2])
    else:
        w=o[1]
        f=lambda a: worst_day_width(d,c,rest,{**extra,k:(a,a+w)})
        return ternary_max(f,o[2],o[3])

def guaranteed_width(frm,to,S):
    c,Lf,Lt=contrast_vars(frm,to)
    tot=F(0)
    Sd=collections.defaultdict(list)
    for k in S: Sd[day[k]].append(k)
    for d in byday:
        if not unk_by_day[d]: continue
        tot+=worst_day_width(d,c,Sd.get(d,[]))
    return tot

def brute_worst(d,c,runs):
    """brute force check for <=2 runs"""
    doms=[]
    for k in runs:
        o=outcome_ranges(k)
        if o is None: continue
        if o[0]=='value': doms.append([(k,(v,v)) for v in range(o[1],o[2]+1)])
        else: doms.append([(k,(a,a+o[1])) for a in range(o[2],o[3]+1)])
    best=None
    for combo in itertools.product(*doms):
        v=day_width_with(d,c,dict(combo))
        if v is not None and (best is None or v>best): best=v
    return best
